export function dialogueById(id:string){return dialogues.find(d=>d.id===id);}
export function dialogueScore(dialogue:Dialogue,choices:readonly number[]):number{
 return dialogue.steps.reduce((n,step,i)=>n+Number(choices[i]===step.answer),0);
}
export function dialoguePassed(score:number,total:number){return total>0&&score>=Math.ceil(total*2/3);}
